func test_valid_story(validator: StoryValidator) -> bool:
	if not validator:
		return false
	var valid_lines: Array = [
		{"type": "line", "speaker": "Elena", "text": "Ciao!"},
		{"type": "line", "speaker": "Marco", "text": "Bentornata."},
		{"type": "set", "variable": "gemme", "value": 5},
		{
			"type": "line",
			"speaker": "Elena",
			"text": "Hai le gemme.",
			"condition": {"variable": "gemme", "operator": ">=", "value": 1}
		}
	]
	var errors := validator.validate_lines(valid_lines, "test_valid.json")
	return errors.is_empty()


